import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const BACKEND_URL = "http://localhost:34101"; // Adăugat URL-ul backend-ului

const SetupProfile = () => {
    const navigate = useNavigate();
    const [form, setForm] = useState({
        firstName: '',
        lastName: '',
        phone: '',
        about: ''
    });
    const [file, setFile] = useState(null);
    const [loading, setLoading] = useState(false);

    const handleChange = (e) => {
        setForm({ ...form, [e.target.name]: e.target.value });
    };

    const handleFileChange = (e) => {
        if (e.target.files && e.target.files[0]) {
            setFile(e.target.files[0]);
        }
    };

    const handleSubmit = async () => {
        const token = localStorage.getItem("token");
        if (!token) {
            navigate("/");
            return;
        }

        setLoading(true);

        try {
            // 1. Creare profil (fără poza)
            const res = await fetch(`${BACKEND_URL}/profile/setup`, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`
                },
                body: JSON.stringify(form)
            });

            if (res.status === 401 || res.status === 403) {
                localStorage.removeItem("token");
                navigate("/", { state: { expired: true } });
                return;
            }

            if (!res.ok) {
                const errorText = await res.text();
                throw new Error(`Eroare la creare profil: ${errorText}`);
            }

            // 2. Dacă s-a selectat o poză, upload
            if (file instanceof File) {
                const formData = new FormData();
                formData.append("file", file);

                const uploadRes = await fetch(`${BACKEND_URL}/profile/photo`, {
                    method: "POST",
                    headers: {
                        Authorization: `Bearer ${token}`
                    },
                    body: formData
                });

                if (uploadRes.status === 401 || uploadRes.status === 403) {
                    localStorage.removeItem("token");
                    navigate("/", { state: { expired: true } });
                    return;
                }

                if (!uploadRes.ok) {
                    const errorText = await uploadRes.text();
                    throw new Error(`Eroare la upload poză: ${errorText}`);
                }

                setFile(null); // ✅ resetăm fișierul
            }

            // Așteaptă puțin înainte de a naviga pentru a permite serverului să proceseze
            setTimeout(() => {
                navigate("/app/profile");
            }, 500);
        } catch (err) {
            console.error("Eroare:", err);

            // Verifică dacă eroarea este despre JWT expirat
            if (err.message && typeof err.message === 'string' && err.message.includes('JWT expired')) {
                localStorage.removeItem("token");
                navigate("/", { state: { expired: true } });
            } else {
                alert("Eroare: " + err.message);
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="setup-profile-wrapper">
            <h2>Configurează-ți profilul</h2>
            <input name="firstName" placeholder="First Name" onChange={handleChange} />
            <input name="lastName" placeholder="Last Name" onChange={handleChange} />
            <input name="phone" placeholder="Phone" onChange={handleChange} />
            <textarea name="about" placeholder="Despre tine" onChange={handleChange} />
            <input type="file" accept="image/*" onChange={handleFileChange} />
            <button onClick={handleSubmit} disabled={loading}>
                {loading ? "Se salvează..." : "Salvează profil"}
            </button>
        </div>
    );
};

export default SetupProfile;
